package com.eventticketing.payment;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.eventticketing.payment.application.*;
import com.eventticketing.payment.application.PaymentModels.*;
import com.eventticketing.payment.infrastructure.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.security.oauth2.jwt.JwtDecoder;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
@SpringBootTest(properties={"app.messaging.enabled=false","spring.kafka.admin.auto-create=false","app.mock.enabled=true","app.mock.secret=synthetic-test-secret-at-least-32-characters","app.mock-delivery-delay-ms=3600000","app.reconciliation-delay-ms=3600000"}) @AutoConfigureMockMvc @Testcontainers
class PaymentIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withInitScript("init.sql");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired PaymentService payments;@Autowired MockProvider mock;@Autowired ReceiptService receipts;@Autowired PaymentRepository repo;@Autowired PaymentReconciliation reconciliation;@Autowired PaymentAdmin admin;@Autowired ReconciliationRunner runner;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired MockMvc mvc;
 @MockitoBean CommerceClient commerce;@MockitoBean IdentityClient identity;@MockitoBean JwtDecoder decoder;
 final UUID actor=UUID.randomUUID();
 Attempt start(){UUID order=UUID.randomUUID(),attempt=UUID.randomUUID();var snapshot=new CommerceClient.Snapshot(order,actor,UUID.randomUUID(),UUID.randomUUID(),"Test event","PENDING_PAYMENT","PUBLISHED",100000,"VND",Instant.now().plusSeconds(600),"NONE");when(commerce.read(order)).thenReturn(snapshot);when(commerce.claim(eq(order),eq(actor),anyString())).thenReturn(new CommerceClient.Claim(attempt,snapshot));return payments.start(order,actor,UUID.randomUUID().toString());}
 Receipt receipt(Attempt a,String status,long amount){return new Receipt(UUID.randomUUID(),"local-mock","local-event-ticketing",a.id(),a.orderId(),"MOCK-"+a.id(),amount,"VND",status,Instant.now(),status.equals("SUCCESS")?Instant.now():null);}
 void send(Receipt r)throws Exception{String body=json.writeValueAsString(r);receipts.receive(body,receipts.sign(body));}
 UUID transaction(Attempt a){return db.queryForObject("select id from payment.transactions where attempt_id=?",UUID.class,a.id());}
 UUID result(Attempt a,String reason){UUID p=transaction(a);reconciliation.apply(UUID.randomUUID(),"event.order.payment-result.v1",json.valueToTree(Map.of("paymentId",p,"attemptId",a.id(),"orderId",a.orderId(),"eventId",a.eventId(),"result",reason,"expectedAmount",a.expectedAmount())));return db.queryForObject("select id from payment.exceptions where transaction_id=?",UUID.class,p);}
 @Test void localAttemptReplaysSameClaimAndCannotBeReadByAnotherCustomer(){var a=start();var same=payments.start(a.orderId(),actor,UUID.randomUUID().toString());assertThat(same.id()).isEqualTo(a.id());assertThatThrownBy(()->payments.read(a.id(),UUID.randomUUID(),false)).hasMessageContaining("quyền");assertThatThrownBy(()->payments.start(a.orderId(),UUID.randomUUID(),"test-key-001")).hasMessageContaining("quyền");}
 @Test void validSuccessProducesDurableEvidenceAndOneOutboxFact()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");assertThat(db.queryForObject("select count(*) from payment.outbox where aggregate_id=? and topic='payment.payment.succeeded.v1'",Integer.class,a.orderId())).isEqualTo(1);}
 @Test void forgedSignatureCannotChangeState()throws Exception{var a=start();String body=json.writeValueAsString(receipt(a,"SUCCESS",100000));assertThatThrownBy(()->receipts.receive(body,"forged")).hasMessageContaining("Chữ ký");assertThat(repo.get(a.id()).status()).isEqualTo("PENDING");assertThat(db.queryForObject("select count(*) from payment.transactions where attempt_id=?",Integer.class,a.id())).isZero();}
 @Test void staleOrWrongMerchantReceiptIsRejected()throws Exception{var a=start();var r=receipt(a,"SUCCESS",100000);var bad=new Receipt(r.deliveryId(),r.provider(),"foreign",r.attemptId(),r.orderId(),r.reference(),r.amount(),r.currency(),r.status(),r.deliveredAt(),r.paidAt());assertThatThrownBy(()->send(bad)).hasMessageContaining("Callback sai");var old=new Receipt(r.deliveryId(),r.provider(),r.merchant(),r.attemptId(),r.orderId(),r.reference(),r.amount(),r.currency(),r.status(),Instant.now().minusSeconds(3600),r.paidAt());assertThatThrownBy(()->send(old)).hasMessageContaining("thời gian");}
 @Test void duplicateDeliveryAndTransactionAreIdempotent()throws Exception{var a=start();var r=receipt(a,"SUCCESS",100000);send(r);send(r);send(receipt(a,"SUCCESS",100000));assertThat(db.queryForObject("select count(*) from payment.transactions where attempt_id=?",Integer.class,a.id())).isEqualTo(1);assertThat(db.queryForObject("select count(*) from payment.outbox where aggregate_id=?",Integer.class,a.orderId())).isEqualTo(1);}
 @Test void sameDeliveryIdentityWithChangedBodyFails()throws Exception{var a=start();var r=receipt(a,"SUCCESS",100000);send(r);var changed=new Receipt(r.deliveryId(),r.provider(),r.merchant(),r.attemptId(),r.orderId(),r.reference(),1,r.currency(),r.status(),r.deliveredAt(),r.paidAt());assertThatThrownBy(()->send(changed)).hasMessageContaining("nội dung khác");}
 @Test void concurrentCallbackDeliveriesHaveOneBusinessEffect(){var a=start();try(var pool=Executors.newFixedThreadPool(6)){var futures=new ArrayList<Future<?>>();for(int i=0;i<12;i++)futures.add(pool.submit(()->{try{send(receipt(a,"SUCCESS",100000));}catch(Exception e){throw new RuntimeException(e);}}));futures.forEach(f->{try{f.get(10,TimeUnit.SECONDS);}catch(Exception e){throw new RuntimeException(e);}});}assertThat(db.queryForObject("select count(*) from payment.outbox where aggregate_id=?",Integer.class,a.orderId())).isEqualTo(1);}
 @Test void failureAfterSuccessNeverDowngrades()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));send(receipt(a,"FAILED",100000));assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");assertThat(db.queryForObject("select count(*) from payment.outbox where aggregate_id=?",Integer.class,a.orderId())).isEqualTo(1);}
 @Test void laterVerifiedCollectionOverridesFailedAttempt()throws Exception{var a=start();send(receipt(a,"FAILED",100000));send(receipt(a,"SUCCESS",100000));assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");assertThat(db.queryForObject("select count(*) from payment.outbox where aggregate_id=?",Integer.class,a.orderId())).isEqualTo(2);}
 @Test void unknownRemainsPendingEvenAfterOrderExpiry(){var a=start();mock.choose(a.id(),actor,"UNKNOWN");db.update("update payment.attempts set expires_at=now()-interval '1 second' where id=?",a.id());mock.query(a.id());assertThat(repo.get(a.id()).status()).isEqualTo("PENDING");mock.choose(a.id(),actor,"SUCCESS");mock.query(a.id());assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");}
 @Test void delayedAndLateProviderWaitForDueTime(){var a=start();mock.choose(a.id(),actor,"DELAYED");mock.query(a.id());assertThat(repo.get(a.id()).status()).isEqualTo("PENDING");db.update("update payment.mock_sessions set available_at=now()-interval '1 second' where attempt_id=?",a.id());mock.query(a.id());assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");var b=start();mock.choose(b.id(),actor,"LATE_SUCCESS");assertThat(repo.get(b.id()).availableAt()).isAfter(b.expiresAt());}
 @Test void lostCallbackRecoversByAuthoritativeQuery(){var a=start();mock.choose(a.id(),actor,"LOST_CALLBACK");mock.deliver(a.id(),false);assertThat(repo.get(a.id()).status()).isEqualTo("PENDING");mock.query(a.id());assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");}
 @Test void duplicateScenarioKeepsOneTransaction(){var a=start();mock.choose(a.id(),actor,"DUPLICATE");mock.query(a.id());assertThat(db.queryForObject("select count(*) from payment.transactions where attempt_id=?",Integer.class,a.id())).isEqualTo(1);assertThat(db.queryForObject("select count(*) from payment.receipts where reference=?",Integer.class,"MOCK-"+a.id())).isEqualTo(2);}
 @Test void changedScenarioAfterOutcomeIsRejected(){var a=start();mock.choose(a.id(),actor,"SUCCESS");assertThatThrownBy(()->mock.choose(a.id(),actor,"FAILED")).hasMessageContaining("đã được chọn");}
 @Test void wrongAmountRetainsActualCollectionAndOneException(){var a=start();mock.choose(a.id(),actor,"WRONG_AMOUNT");mock.query(a.id());UUID id=result(a,"AMOUNT_MISMATCH");result(a,"AMOUNT_MISMATCH");var c=admin.detail(id);assertThat(((Number)c.get("received_amount")).longValue()).isEqualTo(101000);assertThat(c.get("status")).isEqualTo("OPEN");assertThat(db.queryForObject("select count(*) from payment.exceptions where transaction_id=?",Integer.class,transaction(a))).isEqualTo(1);}
 @Test void lateSuccessCaseDoesNotPretendApplied()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));UUID id=result(a,"LATE_SUCCESS");assertThat(repo.get(a.id()).result()).isEqualTo("LATE_SUCCESS");assertThat(admin.detail(id).get("returned_amount")).isEqualTo(0L);}
 @Test void eventCancellationOpensReturnObligation()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));reconciliation.apply(UUID.randomUUID(),"event.event.cancelled.v1",json.valueToTree(Map.of("id",a.eventId())));assertThat(db.queryForObject("select type from payment.exceptions where event_id=?",String.class,a.eventId())).isEqualTo("EVENT_CANCELLED");}
 @Test void unknownTransactionIsRecordedWithoutInventingOrder()throws Exception{var a=start();var r=receipt(a,"SUCCESS",100000);send(new Receipt(r.deliveryId(),r.provider(),r.merchant(),UUID.randomUUID(),UUID.randomUUID(),"UNKNOWN-"+UUID.randomUUID(),100000,"VND","SUCCESS",Instant.now(),Instant.now()));assertThat(repo.get(a.id()).status()).isEqualTo("PENDING");assertThat(db.queryForObject("select count(*) from payment.exceptions where type='UNMATCHED_TRANSACTION'",Integer.class)).isGreaterThan(0);}
 @Test void refundRequiresReviewEvidenceAndCorrectOutstandingAmount()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));UUID id=result(a,"LATE_SUCCESS");var input=new Return("MOCK-RETURN-"+UUID.randomUUID(),100000,"VND","Simulated return evidence",Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS));assertThatThrownBy(()->admin.resolve(id,actor,input)).hasMessageContaining("nhận xử lý");admin.review(id,actor,"Review local case");assertThatThrownBy(()->admin.resolve(id,actor,new Return(input.reference(),200000,"VND",input.evidence(),input.returnedAt()))).hasMessageContaining("không vượt");assertThatThrownBy(()->admin.resolve(id,actor,new Return(input.reference(),100000,"USD",input.evidence(),input.returnedAt()))).hasMessageContaining("tiền tệ");assertThat(admin.resolve(id,actor,input).get("status")).isEqualTo("RESOLVED");assertThat(admin.resolve(id,actor,input).get("status")).isEqualTo("RESOLVED");send(receipt(a,"SUCCESS",100000));assertThat(repo.get(a.id()).status()).isEqualTo("REFUNDED");}
 @Test void partialReturnKeepsCaseOpenAndReviewerScope()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));UUID id=result(a,"LATE_SUCCESS");admin.review(id,actor,"Review");assertThatThrownBy(()->admin.review(id,UUID.randomUUID(),"Other reviewer")).hasMessageContaining("khác");var input=new Return("MOCK-RETURN-"+UUID.randomUUID(),30000,"VND","Partial simulated evidence",Instant.now());assertThat(admin.resolve(id,actor,input).get("status")).isEqualTo("IN_REVIEW");assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");}
 @Test void queryRunIsAuditedAndDoesNotCreateAttempt(){var a=start();mock.choose(a.id(),actor,"LOST_CALLBACK");var run=runner.run(actor);assertThat(run.get("id")).isNotNull();assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");assertThat(db.queryForObject("select count(*) from payment.attempts where order_id=?",Integer.class,a.orderId())).isEqualTo(1);}
 @Test void foreignAndNonAdminRoutesAreDenied()throws Exception{var a=start();mvc.perform(get("/api/v1/local-payments/"+a.id()).with(jwt().jwt(j->j.subject(UUID.randomUUID().toString())))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/admin/payment-exceptions").with(jwt())).andExpect(status().isForbidden());mvc.perform(post("/api/v1/webhooks/payments/local-mock").contentType("application/json").header("X-Mock-Signature","bad").content("{}")).andExpect(status().isUnauthorized());}
 @Test void incompleteSignedReceiptIsRejectedWithoutPersisting()throws Exception{var a=start();for(String field:List.of("currency","status")){var body=json.valueToTree(receipt(a,"SUCCESS",100000));((com.fasterxml.jackson.databind.node.ObjectNode)body).remove(field);String raw=json.writeValueAsString(body);mvc.perform(post("/api/v1/webhooks/payments/local-mock").contentType("application/json").header("X-Mock-Signature",receipts.sign(raw)).content(raw)).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("PAYMENT_VALIDATION"));}assertThat(repo.get(a.id()).status()).isEqualTo("PENDING");assertThat(db.queryForObject("select count(*) from payment.transactions where attempt_id=?",Integer.class,a.id())).isZero();}
 @Test void nanosecondEvidenceReplayPreservesOneReturnAndConflictingReuseFails()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));UUID id=result(a,"LATE_SUCCESS");admin.review(id,actor,"Review precision and replay");Instant timestamp=Instant.now().minusMillis(1).truncatedTo(java.time.temporal.ChronoUnit.MILLIS).plusNanos(123456);var input=new Return("MOCK-RETURN-"+UUID.randomUUID(),100000,"VND","Simulated return evidence with precise time",timestamp);assertThat(admin.resolve(id,actor,input).get("status")).isEqualTo("RESOLVED");assertThat(admin.resolve(id,actor,input).get("status")).isEqualTo("RESOLVED");assertThat(db.queryForObject("select count(*) from payment.return_evidence where exception_id=?",Integer.class,id)).isEqualTo(1);assertThatThrownBy(()->admin.resolve(id,actor,new Return(input.reference(),1,input.currency(),input.evidence(),timestamp))).hasMessageContaining("nội dung khác");}

 @Autowired FinancialLedger ledger;
 @Test void gatewayZeroRequiresMatchingLocalLedgerAndReconciliationPublishesFact()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));ledger.reconcile();var first=json.valueToTree(ledger.snapshot(a.eventId()));assertThat(first.path("transactions").get(0).path("fee_vnd").isNull()).isTrue();db.update("update payment.mock_sessions set status='SUCCESS',received_amount=100000,available_at=now()-interval '1 second' where attempt_id=?",a.id());ledger.reconcile();var known=json.valueToTree(ledger.snapshot(a.eventId())).path("transactions").get(0);assertThat(known.path("fee_vnd").asLong(-1)).isZero();assertThat(known.path("provenance").asText()).isEqualTo("LOCAL_PROVIDER_LEDGER");assertThat(known.path("reconciled_at").isNull()).isFalse();assertThat(db.queryForObject("select count(*) from payment.outbox where aggregate_id=? and topic='payment.payment.financial-updated.v1'",Integer.class,a.eventId())).isGreaterThan(0);}
 @Test void unknownCollectionChangesEveryKnownFinancialSnapshot()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));long before=db.queryForObject("select version from payment.financial_versions where event_id=?",Long.class,a.eventId());var r=receipt(a,"SUCCESS",100000);send(new Receipt(UUID.randomUUID(),r.provider(),r.merchant(),UUID.randomUUID(),UUID.randomUUID(),"UNKNOWN-"+UUID.randomUUID(),100000,"VND","SUCCESS",Instant.now(),Instant.now()));assertThat(db.queryForObject("select version from payment.financial_versions where event_id=?",Long.class,a.eventId())).isGreaterThan(before);assertThat(json.valueToTree(ledger.snapshot(a.eventId())).path("openExceptions").size()).isGreaterThan(0);}
 @Test void partialReturnIsPublishedBeforeCaseIsResolved()throws Exception{var a=start();send(receipt(a,"SUCCESS",100000));UUID id=result(a,"LATE_SUCCESS");admin.review(id,actor,"Review partial reporting");long before=db.queryForObject("select version from payment.financial_versions where event_id=?",Long.class,a.eventId());admin.resolve(id,actor,new Return("MOCK-RETURN-"+UUID.randomUUID(),30000,"VND","Partial simulated evidence",Instant.now()));var snapshot=json.valueToTree(ledger.snapshot(a.eventId()));assertThat(snapshot.path("returns").get(0).path("amount").asLong()).isEqualTo(30000);assertThat(db.queryForObject("select version from payment.financial_versions where event_id=?",Long.class,a.eventId())).isGreaterThan(before);assertThat(repo.get(a.id()).status()).isEqualTo("SUCCESS");}

 @Test void unmatchedCollectionPublishesItsOwnCashLedgerWithoutAnyEventAssignment()throws Exception{UUID unknown=UUID.randomUUID();send(new Receipt(UUID.randomUUID(),"local-mock","local-event-ticketing",unknown,UUID.randomUUID(),"MOCK-UNMAPPED-"+unknown,123,"VND","SUCCESS",Instant.now(),Instant.now()));var rows=db.queryForList("select body->'payload' as payload from payment.outbox where topic='payment.payment.financial-updated.v1' and body->'payload'->>'ledgerScope'='UNMAPPED' order by created_at desc");assertThat(rows).isNotEmpty();var payload=json.readTree(rows.getFirst().get("payload").toString());assertThat(payload.path("eventId").isNull()).isTrue();assertThat(payload.path("ledgerId").asText()).isNotBlank();assertThat(payload.path("transactions").findValuesAsText("reference")).contains("MOCK-UNMAPPED-"+unknown);assertThat(payload.path("openExceptions").size()).isGreaterThan(0);}
}
